WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.Score, p.ViewCount, u.DisplayName AS OwnerDisplayName, ROW_NUMBER() OVER (PARTITION BY p.PostTypeId ORDER BY p.Score DESC NULLS FIRST) AS Rank FROM Posts AS p JOIN Users AS u ON p.OwnerUserId = u.Id WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), RecentCloseReasons AS (SELECT ph.PostId, GROUP_CONCAT(cr.Name, ', ') AS CloseReasons FROM PostHistory AS ph JOIN CloseReasonTypes AS cr ON CAST(ph.Comment AS Nullable(Int32)) = cr.Id WHERE ph.PostHistoryTypeId IN (10, 11) GROUP BY ph.PostId), UserVotes AS (SELECT v.PostId, SUM(CASE WHEN v.VoteTypeId = 2 THEN 1 ELSE 0 END) AS UpVotes, SUM(CASE WHEN v.VoteTypeId = 3 THEN 1 ELSE 0 END) AS DownVotes, COUNT(v.Id) AS TotalVotes FROM Votes AS v GROUP BY v.PostId) SELECT rp.PostId, rp.Title, rp.CreationDate, rp.Score, rp.ViewCount, rp.OwnerDisplayName, COALESCE(rcr.CloseReasons, 'No Close Reasons') AS CloseReasons, COALESCE(uv.UpVotes, 0) AS UpVotes, COALESCE(uv.DownVotes, 0) AS DownVotes, uv.TotalVotes FROM RankedPosts AS rp LEFT JOIN RecentCloseReasons AS rcr ON rp.PostId = rcr.PostId LEFT JOIN UserVotes AS uv ON rp.PostId = uv.PostId WHERE rp.Rank <= 5 ORDER BY rp.PostId, rp.Score DESC NULLS FIRST